import { test, expect } from '@playwright/test';

test.describe('JavaScript Error Recovery', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
  });

  test('should display error boundary when JavaScript error occurs', async ({ page }) => {
    await page.setContent(`
      <html>
        <body>
          <div id="root">
            <button id="error-trigger">Trigger Error</button>
            <div id="error-boundary" style="display:none; padding: 20px; background: #fee; border: 1px solid #f00;">
              <h2>Something went wrong</h2>
              <p>The application encountered an error. Please refresh the page.</p>
              <button id="retry-button">Retry</button>
            </div>
          </div>
          <script>
            const errorBoundary = document.getElementById('error-boundary');
            const root = document.getElementById('root');
            const triggerButton = document.getElementById('error-trigger');
            const retryButton = document.getElementById('retry-button');

            triggerButton.addEventListener('click', () => {
              try {
                throw new Error('Simulated JavaScript error');
              } catch (error) {
                console.error('Error caught:', error);
                root.style.display = 'none';
                errorBoundary.style.display = 'block';
              }
            });

            retryButton.addEventListener('click', () => {
              errorBoundary.style.display = 'none';
              root.style.display = 'block';
            });
          </script>
        </body>
      </html>
    `);

    const triggerButton = page.getByRole('button', { name: 'Trigger Error' });
    await expect(triggerButton).toBeVisible();
  });

  test('should show error message when error is triggered', async ({ page }) => {
    await page.setContent(`
      <html>
        <body>
          <div id="root">
            <button id="error-trigger">Trigger Error</button>
            <div id="error-boundary" style="display:none; padding: 20px; background: #fee; border: 1px solid #f00;">
              <h2>Something went wrong</h2>
              <p>The application encountered an error. Please refresh the page.</p>
              <button id="retry-button">Retry</button>
            </div>
          </div>
          <script>
            const errorBoundary = document.getElementById('error-boundary');
            const root = document.getElementById('root');
            const triggerButton = document.getElementById('error-trigger');

            triggerButton.addEventListener('click', () => {
              try {
                throw new Error('Simulated JavaScript error');
              } catch (error) {
                console.error('Error caught:', error);
                root.style.display = 'none';
                errorBoundary.style.display = 'block';
              }
            });
          </script>
        </body>
      </html>
    `);

    const triggerButton = page.getByRole('button', { name: 'Trigger Error' });
    await triggerButton.click();

    const errorMessage = page.getByText('Something went wrong');
    await expect(errorMessage).toBeVisible();

    const errorDescription = page.getByText('The application encountered an error. Please refresh the page.');
    await expect(errorDescription).toBeVisible();
  });

  test('should recover from error when retry button is clicked', async ({ page }) => {
    await page.setContent(`
      <html>
        <body>
          <div id="root">
            <button id="error-trigger">Trigger Error</button>
            <div id="error-boundary" style="display:none; padding: 20px; background: #fee; border: 1px solid #f00;">
              <h2>Something went wrong</h2>
              <p>The application encountered an error. Please refresh the page.</p>
              <button id="retry-button">Retry</button>
            </div>
          </div>
          <script>
            const errorBoundary = document.getElementById('error-boundary');
            const root = document.getElementById('root');
            const triggerButton = document.getElementById('error-trigger');
            const retryButton = document.getElementById('retry-button');

            triggerButton.addEventListener('click', () => {
              try {
                throw new Error('Simulated JavaScript error');
              } catch (error) {
                console.error('Error caught:', error);
                root.style.display = 'none';
                errorBoundary.style.display = 'block';
              }
            });

            retryButton.addEventListener('click', () => {
              errorBoundary.style.display = 'none';
              root.style.display = 'block';
            });
          </script>
        </body>
      </html>
    `);

    const triggerButton = page.getByRole('button', { name: 'Trigger Error' });
    await triggerButton.click();

    const errorMessage = page.getByText('Something went wrong');
    await expect(errorMessage).toBeVisible();

    const retryButton = page.getByRole('button', { name: 'Retry' });
    await retryButton.click();

    await expect(errorMessage).not.toBeVisible();
    await expect(triggerButton).toBeVisible();
  });

  test('should handle multiple sequential errors gracefully', async ({ page }) => {
    await page.setContent(`
      <html>
        <body>
          <div id="root">
            <button id="error-trigger">Trigger Error</button>
            <div id="error-count" style="margin-top: 10px;">Errors: 0</div>
            <div id="error-boundary" style="display:none; padding: 20px; background: #fee; border: 1px solid #f00;">
              <h2>Something went wrong</h2>
              <p id="error-details">An error occurred</p>
              <button id="retry-button">Retry</button>
            </div>
          </div>
          <script>
            let errorCount = 0;
            const errorBoundary = document.getElementById('error-boundary');
            const root = document.getElementById('root');
            const triggerButton = document.getElementById('error-trigger');
            const retryButton = document.getElementById('retry-button');
            const errorCountDiv = document.getElementById('error-count');
            const errorDetails = document.getElementById('error-details');

            triggerButton.addEventListener('click', () => {
              try {
                errorCount++;
                throw new Error('Simulated JavaScript error #' + errorCount);
              } catch (error) {
                console.error('Error caught:', error);
                errorDetails.textContent = error.message;
                errorCountDiv.textContent = 'Errors: ' + errorCount;
                root.style.display = 'none';
                errorBoundary.style.display = 'block';
              }
            });

            retryButton.addEventListener('click', () => {
              errorBoundary.style.display = 'none';
              root.style.display = 'block';
            });
          </script>
        </body>
      </html>
    `);

    const triggerButton = page.getByRole('button', { name: 'Trigger Error' });
    const retryButton = page.getByRole('button', { name: 'Retry' });

    // First error
    await triggerButton.click();
    let errorMessage = page.getByText('Simulated JavaScript error #1');
    await expect(errorMessage).toBeVisible();

    // Recover from first error
    await retryButton.click();
    await expect(triggerButton).toBeVisible();

    // Second error
    await triggerButton.click();
    errorMessage = page.getByText('Simulated JavaScript error #2');
    await expect(errorMessage).toBeVisible();

    // Recover from second error
    await retryButton.click();
    await expect(triggerButton).toBeVisible();
  });
});
